label.text:
model -> {
	period = ifElse(isEmpty($model), 30, $model);
	span = ifElse($period == 0,
		#('All'@en, 'Alle'@de).localize(),
		ifElse($period == 1,
			#('1 day'@en, '1 Tag'@de).localize(),
			#('{0} days'@en, '{0} Tage'@de).fill($period).localize()));
	#('Failures ({0})'@en, 'Fehler ({0})'@de).fill($span).localize();
}

description.text:
model -> {
	period = ifElse(isEmpty($model), 30, $model);
	executions = all(`tl.ai.execution:AgentExecution`);
	recent = ifElse($period == 0, $executions,
		$executions.filter(e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`)
			>= now().toSystemCalendar().withDayAdded(-$period).toDate()));
	failed = $recent.filter(e -> $e.get(`tl.ai.execution:AgentExecution#status`) == `tl.ai.execution:ExecutionStatus#ERROR`).size();
	{{{
		<div class="aiKpi">
			<div class="aiKpiValue">{numberFormat('#,##0').format($failed)}</div>
			<div class="aiKpiNote">
				{#('of {0} runs'@en, 'von {0} Läufen'@de).fill($recent.size())}
			</div>
		</div>
	}}};
}

modelBuilder.elements:
model -> {
	period = ifElse(isEmpty($model), 30, $model);
	executions = all(`tl.ai.execution:AgentExecution`);
	ifElse($period == 0, $executions,
			$executions.filter(e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`)
				>= now().toSystemCalendar().withDayAdded(-$period).toDate()))
		.filter(e -> $e.get(`tl.ai.execution:AgentExecution#status`) == `tl.ai.execution:ExecutionStatus#ERROR`);
}
